package me.growapet.commands;import me.growapet.GrowAPet;import me.growapet.models.Pet;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class PetsCommand implements CommandExecutor{private final GrowAPet plugin;public PetsCommand(GrowAPet p){plugin=p;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player p)){s.sendMessage("§cPlayers only.");return true;}if(a.length==2&&(a[0].equalsIgnoreCase("equip")||a[0].equalsIgnoreCase("unequip"))){try{UUID id=UUID.fromString(a[1]);boolean ok=a[0].equalsIgnoreCase("equip")?plugin.getPetManager().equip(p.getUniqueId(),id):plugin.getPetManager().unequip(p.getUniqueId(),id);p.sendMessage(ok?"§aPet updated.":"§cCould not update that pet (check ownership and slot limits).");}catch(IllegalArgumentException e){p.sendMessage("§cInvalid pet UUID.");}return true;}List<Pet>pets=plugin.getPetManager().getPets(p.getUniqueId());p.sendMessage("§d§lYour Pets §7("+pets.size()+") §8- /pets equip|unequip <uuid>");for(Pet pet:pets)p.sendMessage("§7- §e"+pet.getDisplayName()+" §7Lv."+pet.getLevel()+" ["+pet.getUuid()+"] "+(pet.isEquipped()?"§aEQUIPPED":""));return true;}}
